    [TestMethod]
    public void WeekOfYear_DefaultOverload_ShouldDelegateToCurrentCulture()
    {
        DateTime input = new DateTime(2024, 4, 18);
        int expected = input.WeekOfYear(CultureInfo.CurrentCulture);
        int actual = input.WeekOfYear();

